  const emailToId = new Map();
  const order = [];

  const text = (value, name) => {
    if (typeof value !== 'string' || value.trim() === '') {
      throw new TypeError(name + ' must be a non-empty string');
    }
    return value.trim();
  };

  const normalizeEmail = value => text(value, 'email').toLowerCase();
  const digest = secret => {
    if (typeof secret !== 'string' || secret.length < 8) {
      throw new TypeError('secret must contain at least eight characters');
    }
    return crypto.createHash('sha256').update('member-catalog\0' + secret).digest('hex');
  };

  const regions = value => {
    if (!Array.isArray(value) || value.some(item => typeof item !== 'string' || item.trim() === '')) {
      throw new TypeError('regions must be an array of non-empty strings');
    }
    return value.slice();
  };

  const publicRecord = record => ({
    id: record.id,
    displayName: record.displayName,
    email: record.email,
    plan: record.plan,
    regions: record.regions.slice()
  });

  function create(input) {
    if (!input || typeof input !== 'object' || Array.isArray(input)) throw new TypeError('input must be an object');
    const record = {
      id: text(input.id, 'id'),
      displayName: text(input.displayName, 'displayName'),
      email: normalizeEmail(input.email),
      plan: text(input.plan, 'plan'),
      regions: regions(input.regions),
      digest: digest(input.secret)
    };
    if (records.has(record.id)) throw new Error('duplicate id');
    if (emailToId.has(record.email)) throw new Error('duplicate email');
    records.set(record.id, record);
    emailToId.set(record.email, record.id);
    order.push(record.id);
    return publicRecord(record);
  }

  function get(id) {
    const record = records.get(id);
    return record ? publicRecord(record) : null;
  }

