    const current = records.get(id);
    if (!current) return null;
    if (!patch || typeof patch !== 'object' || Array.isArray(patch)) throw new TypeError('patch must be an object');
    const allowed = new Set(['displayName', 'email', 'plan', 'regions', 'secret']);
    for (const key of Object.keys(patch)) if (!allowed.has(key)) throw new TypeError('unknown field: ' + key);
    const next = { ...current, regions: current.regions.slice() };
    if ('displayName' in patch) next.displayName = text(patch.displayName, 'displayName');
    if ('plan' in patch) next.plan = text(patch.plan, 'plan');
    if ('regions' in patch) next.regions = regions(patch.regions);
    if ('secret' in patch) next.digest = digest(patch.secret);
    if ('email' in patch) {
      next.email = normalizeEmail(patch.email);
      const owner = emailToId.get(next.email);
      if (owner !== undefined && owner !== id) throw new Error('duplicate email');
    }
    records.set(id, next);
    if (next.email !== current.email) {
      emailToId.delete(current.email);
      emailToId.set(next.email, id);
    }
    return publicRecord(next);
  }

  function remove(id) {
    const record = records.get(id);
    if (!record) return false;
    records.delete(id);
    emailToId.delete(record.email);
    order.splice(order.indexOf(id), 1);
    return true;
  }

  function authenticate(email, secret) {
    if (typeof email !== 'string' || typeof secret !== 'string') return false;
    const id = emailToId.get(email.trim().toLowerCase());
    const record = id === undefined ? null : records.get(id);
    if (!record || secret.length < 8) return false;
    const candidate = digest(secret);
    return crypto.timingSafeEqual(Buffer.from(record.digest, 'hex'), Buffer.from(candidate, 'hex'));
  }

  function list({ page = 1, pageSize = 20 } = {}) {
    if (!Number.isInteger(page) || page < 1 || !Number.isInteger(pageSize) || pageSize < 1) {
      throw new TypeError('page and pageSize must be positive integers');
    }
    const total = order.length;
    const start = page * pageSize;
    return {
      items: order.slice(start, start + pageSize).map(id => publicRecord(records.get(id))),
      total,
      page,
      pageSize,
      pages: total === 0 ? 0 : Math.ceil(total / pageSize)
    };
  }

  return { create, get, update, remove, authenticate, list };
