'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['createMemberCatalog']);

const catalog = api.createMemberCatalog();
assert.deepStrictEqual(Object.keys(catalog).sort(), ['authenticate', 'create', 'get', 'list', 'remove', 'update']);
assert.deepStrictEqual(catalog.list(), { items: [], total: 0, page: 1, pageSize: 20, pages: 0 });
assert.strictEqual(catalog.get('missing'), null);
assert.strictEqual(catalog.remove('missing'), false);
assert.strictEqual(catalog.authenticate('nobody@example.com', 'password'), false);

const regions = ['IN', 'US'];
catalog.create({ id: 'm1', displayName: 'One', email: 'One@Example.com', plan: 'pro', regions, secret: '12345678' });
regions[0] = 'CHANGED';
assert.deepStrictEqual(catalog.get('m1'), {
  id: 'm1', displayName: 'One', email: 'one@example.com', plan: 'pro', regions: ['IN', 'US']
});
assert.strictEqual(catalog.authenticate('ONE@EXAMPLE.COM', '12345678'), true);
assert.strictEqual(catalog.authenticate('one@example.com', 'wrong-pass'), false);
assert.strictEqual('secret' in catalog.get('m1'), false);
assert.strictEqual('digest' in catalog.get('m1'), false);

catalog.create({ id: 'm2', displayName: 'Two', email: 'two@example.com', plan: 'basic', regions: [], secret: 'abcdefgh' });
assert.throws(() => catalog.create({ id: 'm2', displayName: 'Dup', email: 'dup@example.com', plan: 'x', regions: [], secret: 'abcdefgh' }));
assert.throws(() => catalog.create({ id: 'm3', displayName: 'Dup email', email: 'ONE@example.COM', plan: 'x', regions: [], secret: 'abcdefgh' }));
assert.throws(() => catalog.create({ id: 'm3', displayName: '', email: 'three@example.com', plan: 'x', regions: [], secret: 'abcdefgh' }), TypeError);
assert.throws(() => catalog.create({ id: 'm3', displayName: 'Three', email: 'three@example.com', plan: 'x', regions: [''], secret: 'abcdefgh' }), TypeError);
assert.throws(() => catalog.create({ id: 'm3', displayName: 'Three', email: 'three@example.com', plan: 'x', regions: [], secret: '1234567' }), TypeError);
assert.strictEqual(catalog.get('m3'), null);

const replacementRegions = ['EU'];
catalog.update('m1', { displayName: 'First', email: 'FIRST@example.com', regions: replacementRegions, secret: 'new-pass' });
replacementRegions.push('APAC');
assert.deepStrictEqual(catalog.get('m1'), {
  id: 'm1', displayName: 'First', email: 'first@example.com', plan: 'pro', regions: ['EU']
});
assert.strictEqual(catalog.authenticate('one@example.com', '12345678'), false);
assert.strictEqual(catalog.authenticate('FIRST@EXAMPLE.COM', 'new-pass'), true);

const beforeFailedUpdate = catalog.get('m1');
assert.throws(() => catalog.update('m1', { displayName: 'Corrupted', email: 'two@example.com' }));
assert.deepStrictEqual(catalog.get('m1'), beforeFailedUpdate);
assert.throws(() => catalog.update('m1', { plan: 'changed', unknown: true }), TypeError);
assert.deepStrictEqual(catalog.get('m1'), beforeFailedUpdate);

const publicCopy = catalog.get('m1');
publicCopy.displayName = 'mutated';
publicCopy.regions.push('mutated');
assert.deepStrictEqual(catalog.get('m1'), beforeFailedUpdate);

assert.deepStrictEqual(catalog.list({ page: 1, pageSize: 1 }), {
  items: [beforeFailedUpdate], total: 2, page: 1, pageSize: 1, pages: 2
});
assert.deepStrictEqual(catalog.list({ page: 3, pageSize: 1 }), {
  items: [], total: 2, page: 3, pageSize: 1, pages: 2
});
const listing = catalog.list();
listing.items[0].regions.push('leak');
listing.items.length = 0;
assert.strictEqual(catalog.list().items.length, 2);
assert.deepStrictEqual(catalog.get('m1').regions, ['EU']);
for (const options of [{ page: 0 }, { page: 1.5 }, { pageSize: 0 }, { pageSize: 2.5 }]) {
  assert.throws(() => catalog.list(options), TypeError);
}
assert.strictEqual(catalog.remove('m1'), true);
assert.strictEqual(catalog.remove('m1'), false);
assert.strictEqual(catalog.get('m1'), null);
assert.strictEqual(catalog.authenticate('first@example.com', 'new-pass'), false);

